// The channel contract, typed so the compiler enforces the rules:
interface Channel<T> {
  send(v: T): Promise<void>;      // returns a Promise: BACKPRESSURE by awaiting
  receive(): Promise<T>;          // resolves when an item is available or the channel closes
  close(reason?: Error): void;    // close: reject/resolve EVERY waiter
}

// The pull-based channel: an async generator, with natural backpressure.
async function* rows(cursor: Cursor): AsyncGenerator<Row, void, undefined> {
  for await (const r of cursor.stream()) yield r;   // suspends until the consumer pulls
}
for await (const row of rows(cursor)) { await handle(row); }   // typed, checked

// Cancellation is AbortSignal: reject every waiting promise on abort, or they hang.
// For multi-worker or strict FIFO, use a library queue (p-queue / it-channel);
// hand-rolled queues lose wakeups and fairness in ways the types cannot catch.
